/*
 Problem: 4000. Largest Integer With Given Digit Sum
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.3 MB (51.83%)
 Tags: Math, Greedy
*/
class Solution {
public:
    int largestInteger(int n, int s) {
        if (n * 9 < s) return -1;

        int ans = 0;

        while (n--) {
            int v = min(9, s);
            ans = ans * 10 + min(9, s);
            s -= v;
        }

        return ans;
    }
};
